  str_n29_detective_clue_name_25 = "Ensaio",
  str_n29_detective_clue_name_26 = "Limpeza repentina",
  str_n29_detective_clue_name_27 = "pirralho indesejado",
  str_n29_detective_clue_name_28 = "Substituição",
  str_n29_detective_clue_name_29 = "Outro Registro",
  str_n29_detective_clue_name_30 = "Livro de Roteiro Sujo",
  str_n29_detective_clue_name_31 = "Machado",
  str_n29_detective_clue_name_32 = "Vira-latas",
  str_n29_detective_clue_name_33 = "um assunto importante",
  str_n29_detective_clue_desc_1 = "Hati ouve duas vozes estranhas conversando quando ela está meio adormecida.\nDizem que ela é uma criança solitária, com uma personalidade teimosa e insociável que a maioria das pessoas não gosta.\nEles também dizem que ela é muito forte e não consegue se controlar, e muitas vezes ela incendeia as coisas.\nNinguém jamais iria querer um filho assim.",
  str_n29_detective_clue_desc_2 = "Crianças impopulares são chamadas de \"pirralhos\" no orfanato.\nDizem que não adianta segurar essas crianças e que é hora de mandar Hati ausente.",
  str_n29_detective_clue_desc_3 = "Senhorita Babá conta Hati que o orfanato é seu novo lar.\nA mãe dela não pode estar com ela agora... mas a Srta. Babá pode.\nHá um monte de crianças legais aqui, e a Srta. Childminder pensa Hati poderá viver feliz com todos.",
  str_n29_detective_clue_desc_4 = "O limpador diz Hati que orfanatos são lugares que acolhem crianças indesejadas.\nE a mãe de Hati a largou aqui deve ser porque ela a odeia.\nNinguém se importa com filhos sem pais, eles são como pedras na beira da estrada, e as pessoas simplesmente os chutam para fora do caminho.\nA partir de agora, tudo o que está por vir Hati é uma vida vivida em um inferno constante.",
  str_n29_detective_clue_desc_5 = "Essas luvas de aparência familiar estão úmidas na superfície.\nHati tinha visto luvas como essas antes - sua mãe usava luvas semelhantes a elas durante a limpeza.\nHati lembrou que a mãe dela disse que as luvas facilitavam as coisas.",
  str_n29_detective_clue_desc_6 = "Um pequeno saco de pão.\nParece que entrou um pouco de água e agora o pão está todo encharcado e com um cheiro de mofo.\nHati diz que o pão que sua mãe lhe dava sempre cheirava tão bem e era tão macio.\nParece que ela sente falta da mãe...",
  str_n29_detective_clue_desc_7 = "Essa menina diz que tem muitos amiguinhos divertidos no orfanato.\nTodos brincam com brinquedos, desenham, comem e cochilam juntos todos os dias. Nunca fica chato aqui!\nMas também existem algumas crianças más... seria melhor se Hati ficou longe deles.",
  str_n29_detective_clue_desc_8 = "Você sabe o que é um \"brat\"?\nÉ uma criança que ninguém gosta.\nComo O Rei Malvado. Todo mundo acha que ele é um verdadeiro pé no saco, e seu pequeno parasita viscoso também!\nMas ninguém tem medo desses pirralhos porque todo mundo sabe que os pirralhos têm o que merecem.\nCrianças boas ganham doces e crianças más são punidas. Aquela menina diz que é sempre assim no orfanato.",
  str_n29_detective_clue_desc_9 = "Esse hang-on realmente adora viver no orfanato.\nA grande e misericordiosa Senhora Diretora, sua compaixão permitiu que as crianças desabrigadas recebessem o cuidado e o calor de uma família!\nMas essa felicidade é passageira.\nAs melhores crianças são enviadas para famílias ricas todos os meses para levar uma vida despreocupada. As crianças horríveis são enviadas para famílias pobres, onde ninguém realmente se importa com elas.\nMas tudo bem - aquele parasita ainda tem seu mantra secreto. Enquanto você continuar bajulando os adultos, mesmo que eles não gostem muito de você, pelo menos vão deixá-lo em paz por um tempo.",
  str_n29_detective_clue_desc_10 = "O Rei Malvado diz que é o personagem principal do orfanato!\nEle é o mais popular, todo mundo tem que prestar atenção nele, e todos os brinquedos são dele também!\nVeja, ele até foi escolhido para o papel principal na peça amanhã à noite... Bem, é natural, já que ele é o único que importa neste lugar!\nJá aquele parasita, a garota legal e os adultos no palco com ele, são apenas adereços, para destacar ainda mais o personagem principal.\nMas aquela garota é ainda mais popular que o Rei Malvado... e ele não aguenta!",
  str_n29_detective_clue_desc_11 = "A senhorita Childminder diz que os adultos gostam de crianças sensatas.\nDesde que Hati ajuda mais pessoas, com certeza todos vão gostar dela!",
  str_n29_detective_clue_desc_12 = "Um envelope lindo e perfeito com um selo vermelho brilhante...\nEssa carta parece tão nobre e deslocada neste orfanato decadente quanto a Senhora Diretora.",
  str_n29_detective_clue_desc_13 = "O entregador afirma que perdeu algo.\nEle descreve que é algo branco e macio que as crianças adorariam.\nQuanto ao que é exatamente... bem, aquele velho tem uma memória muito ruim - ele esqueceu completamente!",
  str_n29_detective_clue_desc_14 = "Aquele homem meio corcunda disse que era um investidor do orfanato.\nVeja, a lista de crianças em sua mão prova suas palavras. Todas as crianças que já estiveram aqui foram gravadas nele.\nEle diz que investiu muito dinheiro para que todos possam ter uma vida boa aqui - para que todos tenhamos roupas e comida para comer.",
  str_n29_detective_clue_desc_15 = "Miss Childminder está muito estressada porque seu salário é muito baixo.\nMas parece que ela é a única com problemas de dinheiro neste lugar. Ela diz que até o zelador ri dela por ser tão pobre...\nEla é tão gentil com todos e obviamente trabalha tanto, então por que a vida dela não é tão boa quanto a daquela faxineira preguiçosa?\nA senhorita Childminder diz que é porque os adultos sempre afastam as pessoas de quem não gostam.",
  str_n29_detective_clue_desc_16 = "Há um desenho a giz de cera na cama do Rei Malvado.\nÉ a foto de uma criança deitada em algum lugar que guarda um monte de coisas, com uma coisa suja e esbranquiçada ao lado...\nHonestamente, a imagem é uma bagunça, isso é tudo Hati poderia realmente entender.",
  str_n29_detective_clue_desc_17 = "Essa bolsa com o buraco parece que foi usada por muito tempo.\nÉ tão leve que até faz um som de farfalhar quando você o agita.",
  str_n29_detective_clue_desc_18 = "Esta imagem de giz de cera está no chão do lado de fora.\nÉ um desenho de três pessoas - uma mulher chorando, um homem zangado e uma criança sendo espancada.",
  str_n29_detective_clue_desc_19 = "Um brinquedo de cordeiro imundo.\nEstá coberto de lama, assim como algumas marcas vermelhas escuras.",
  str_n29_detective_clue_desc_20 = "A Srta. Babá diz que muitos ricos virão ver a peça amanhã. Eles vão adotar as crianças que tiverem um bom desempenho.\nEsta recompensa é apenas para crianças boas.\nHati ajuda a Srta. Babá a encontrar sua bolsa, e ela diz Hati deveria até tentar se apresentar no palco também.",
  str_n29_detective_clue_desc_21 = "Aquele entregador diz que devemos dar às pessoas que cometem erros uma chance de compensá-los em particular.\nEssa é a boa vontade dos adultos.\nO mundo dos adultos é complicado, então eles tentariam resolver os problemas de forma pacífica e sensata. É para o bem de todos.",
  str_n29_detective_clue_desc_22 = "Você sabe por que viver em um orfanato é tão feliz?\nPorque todos os adultos aqui amam muito as crianças.\nTodos trabalham aqui para nos dar seu amor sem esperar nada em troca.\nPor isso precisamos aprender a ser gratos.",
  str_n29_detective_clue_desc_23 = "Uma velha boneca quebrada.\nÉ óbvio que quem quer que seja, eles adoraram muito.\nAcho que não importa o quanto você ame alguma coisa, ela envelhecerá e quebrará depois que o tempo passar.",
  str_n29_detective_clue_desc_24 = "O orfanato realiza uma festa no final de cada mês. É um dos eventos mais importantes aqui.\nA maioria das crianças costuma se comportar bem nessas festas e tenta parecer uma criança boa e popular para mostrar a todos o seu melhor lado.\n\nDeve ser porque outro evento importante ocorre logo após a festa noturna no final do mês - o dia da adoção, quando crianças boas e más deixam o orfanato para seus novos lares.",
  str_n29_detective_clue_desc_25 = "Hati tem que começar o ensaio agora para a peça para ter certeza de que ela aprendeu todas as falas antes da apresentação!\nTodos estão ocupados se preparando para a festa, então ninguém tem tempo para ajudar Hati...\nHati agora tem que ir aos bastidores sozinho para encontrar adereços e depois ir para a sala do diretor para encontrar o roteiro.",
  str_n29_detective_clue_desc_26 = "Hoje de manhã cedo, aquele parasita viu o zelador limpando a cama do Rei Malvado e levando suas coisas para a porta dos fundos para entregar ao entregador.\nPara onde o Rei Malvado poderia ter ido?",
  str_n29_detective_clue_desc_27 = "Uma personalidade podre, comportamento vil, uma onda de violência imprevisível...\nNinguém jamais iria querer um pirralho assim.\nÉ por isso que ninguém jamais adotaria o Rei Malvado, entende?",
  str_n29_detective_clue_desc_28 = [[
O Rei Malvado partiu, e Hati ocupou seu lugar como personagem principal.
Aquele entregador disse Hati deveria gastar menos tempo se preocupando com o Rei Malvado e mais tempo se preocupando consigo mesma.]],
  str_n29_detective_clue_desc_29 = "Este registro é muito semelhante ao que o investidor carrega consigo.\nA única diferença é que todas essas marcas estão ao lado dos nomes das crianças.\nAlgumas estão riscadas e outras marcadas.\nVá para a página mais recente e o nome de Hati estará na página. O nome do Rei Malvado também está nele.\nO Rei Malvado, Hati, o hang-on, a garota legal ... Eles estão todos nisso e estão todos marcados com cruzes vermelhas brilhantes. O que isso poderia significar?",
  str_n29_detective_clue_desc_30 = "Metade de um livro de roteiro sujo está manchado com tinta vermelha escura.\nA tinta cheira um pouco a peixe... que estranho.",
  str_n29_detective_clue_desc_31 = "Um machado curto.\nHá muitas marcas de ferrugem nela, mas a lâmina é polida e muito afiada.\nUma coisa perigosa como essa não deveria ser usada como suporte de performance...",
  str_n29_detective_clue_desc_32 = "Hati deixa a Srta. Babá com raiva.\nSenhorita Babá diz que Hati não deve tratar coisas perigosas tão descuidadamente.\nApenas cães vadios pegam coisas sem pensar.\nÉ Hati um cão vadio?",
  str_n29_detective_clue_desc_33 = "A garota diz algo muito sério para Hati sobre como ela deveria tentar dizer a diferença entre o que é importante e o que não é.\nNão representamos peças apenas para ser bons pequenos atores. É sobre se tornar crianças fofas, simpáticas e inteligentes, se tornar uma criança que as pessoas estão dispostas a levar para casa.\nComparado a isso, nada mais importa.\nEssas palavras soam um pouco familiares. Ah, sim, mamãe costumava dizer isso sobre os bolos na vitrine.",
  str_n29_detective_fragment_name_1 = "A situação no orfanato",
  str_n29_detective_fragment_name_2 = "A Revolta do Brat",
  str_n29_detective_fragment_name_3 = "Um orfanato de amor",
  str_n29_detective_fragment_name_4 = "A Festa da Noite Especial",
  str_n29_detective_fragment_name_5 = "O paradeiro do Rei Malvado",
  str_n29_detective_fragment_name_6 = "Hati o pirralho",
  str_n29_detective_fragment_name_7 = "Monstros Reais",
  str_n29_detective_fragment_desc_1 = "Este orfanato é um lugar para crianças desabrigadas.\nNão é muito grande e as instalações estão em ruínas, mas a Srta. Babá faz o possível para cuidar de nós.\nExistem pessoas boas e más entre as crianças e os adultos. A mãe de Hati disse uma vez que o mundo lá fora também é assim, e que Hati precisa aprender a se adaptar a ela.",
  str_n29_detective_fragment_desc_2 = "Todo mundo odeia o Rei Malvado.\nEle é agressivo, desleixado e gosta de intimidar todo mundo.\nMas ninguém se incomoda muito com ele. Isso porque crianças más são mandadas embora no final de cada mês. Apenas crianças boas ficam no orfanato e são enviadas para boas famílias.",
  str_n29_detective_fragment_desc_3 = "Os adultos são bons em delegar e cooperar.\nNeste orfanato carinhoso, algumas pessoas são responsáveis por investir, outras por nos dar amor e outras por ganhar dinheiro em tempos de desespero.\nNo entanto, parece que apenas a responsável por nos dar amor é criticada pelos outros adultos e, como resultado, sua vida se tornou miserável.",
  str_n29_detective_fragment_desc_4 = "No final de cada mês, o orfanato realiza um evento especial: uma festa noturna.\nNa festa, as crianças se apresentam para alguns adultos que nunca viram antes. As crianças com melhor desempenho são adotadas por famílias ricas.\nA apresentação deste mês é uma peça de teatro. O Rei Malvado interpreta o herói, a garota legal interpreta a princesa e a babá e a babá interpretam os aldeões. A garota legal tira todos os holofotes de The Wicked King, e isso realmente o deixa louco.",
  str_n29_detective_fragment_desc_5 = "Antes de desaparecer, o Rei Malvado estava com ciúmes da garota legal e ia fazer algo ruim com ela. Ele roubou a boneca dela e entrou furtivamente na carruagem do entregador. Mas depois de ver o que viu, ele finalmente mudou de ideia. Depois de fugir com pressa, ele desenhou o que viu.\nOntem, o entregador disse que resolveria o problema em particular para evitar constrangimento. Hoje, o Rei Malvado desapareceu.\nO entregador diz que ele foi adotado. Mas olhando para este livro de roteiro sujo, talvez o zelador estivesse certo...",
  str_n29_detective_fragment_desc_6 = "No começo, as pessoas não gostaram Hati.\nHati tentou muito fazer todos felizes.\nMas mesmo agora... as pessoas ainda não gostam dela.",
  str_n29_detective_fragment_desc_7 = "Eles lidam secretamente com as crianças más.\nAqueles adultos que só se preocupam com dinheiro estão lucrando com isso.\nAs crianças problemáticas serão tratadas o mais rápido possível, o que significa que os dias de Hati estão contados.",
  str_n29_detective_end_name_1 = "Adeus, pirralho",
  str_n29_detective_end_name_2 = "Adeus, Pesadelo",
  str_n29_detective_end_desc_1 = "Ladrões, cachorros vadios, monstrinhos...\nNinguém brinca com você. Ninguém gosta de ti.\nDesapareça daqui, rapidamente!",
  str_n29_detective_end_desc_2 = "Fugir.\nLivremente, sempre voltado para frente.\nNunca olhar para trás.",
  str_n29_detective_point_lockname_3 = "Uma garota",
  str_n29_detective_point_lockname_4 = "criança desleixada",
  str_n29_detective_point_lockname_5 = "criança selvagem",
  str_n29_detective_point_lockname_6 = "velha",
  str_n29_detective_point_lockname_7 = "o homem gordo",
  str_n29_detective_point_lockname_8 = "O Cavalheiro Corcunda",
  str_n29_detective_point_lockname_9 = "Um lugar para dormir",
  str_n29_detective_point_lockname_10 = "o gramado",
  str_n29_detective_point_lockname_11 = "Atrás da cortina",
  str_n29_detective_point_lockname_12 = "Um Quarto Diferente",
  str_n29_detective_point_name_1 = "Babá",
  str_n29_detective_point_name_2 = "Limpador",
  str_n29_detective_point_name_3 = "menina gentil",
  str_n29_detective_point_name_4 = "Lacaio",
  str_n29_detective_point_name_5 = "O Rei Malvado",
  str_n29_detective_point_name_6 = "velho reitor",
  str_n29_detective_point_name_7 = "Mensageiro",
  str_n29_detective_point_name_8 = "Investidor",
  str_n29_detective_point_name_9 = "O dormitório",
  str_n29_detective_point_name_10 = "O Jardim",
  str_n29_detective_point_name_11 = "Nos bastidores",
  str_n29_detective_point_name_12 = "Gabinete do Diretor",
  str_n29_detective_point_lockdesc_3 = "A outra criança na sala.\n\n<color=#902121>Hati não quer falar com ela agora.</color>",
  str_n29_detective_point_lockdesc_4 = "Ele sempre segue atrás de crianças mais duras com um sorriso repulsivo.\n\n<color=#902121>Hati não quer falar com ele se estiver tudo bem.</color>",
  str_n29_detective_point_lockdesc_5 = "Uma criança com uma voz alta que parece muito agressiva.\n\n<color=#902121>Fique longe dele, se possível.</color>",
  str_n29_detective_point_lockdesc_6 = "A velha vestida de preto sempre olha Hati com desaprovação em seus olhos.\n\n<color=#902121>É melhor não incomodá-la se estiver tudo bem.</color>",
  str_n29_detective_point_lockdesc_7 = "Aquele gordo, a carruagem ao lado dele é dele?\n\n<color=#902121>Não o perturbe, a menos que seja absolutamente necessário.</color>",
  str_n29_detective_point_lockdesc_8 = "Este velhinho corcunda parece bastante próspero.\nPor algum motivo, Hati não gosta dele.\n\n<color=#902121>Hati não quer falar com ele se isso não for um problema.</color>",
  str_n29_detective_point_lockdesc_9 = "Hati costumava dormir abraçada à mãe.\nMãe...\n\n<color=#902121>Hati não está com vontade de explorar aqui por enquanto.</color>",
  str_n29_detective_point_lockdesc_10 = "Hati nunca teve permissão para brincar quando morava com a mãe.\nRolar no gramado é bom?\nMas nenhuma das outras crianças saiu para brincar...\n\n<color=#902121>Hati é uma criança boa e obediente. Volte aqui apenas quando precisar.</color>",
  str_n29_detective_point_lockdesc_11 = "O que está por trás da cortina?\nEu realmente quero levantar o véu e ver o que há lá.\nMas os adultos disseram que não podemos brincar aqui...\n\n<color=#902121>Hati é uma criança boa e obediente. Volte aqui apenas quando precisar.</color>",
  str_n29_detective_point_lockdesc_12 = "Essa porta ficou muito linda. É tão grosso e tão diferente de qualquer outro lugar.\nNo entanto, o proprietário não gosta que as pessoas entrem aqui sem permissão...\n\n<color=#902121>Hati é uma criança boa e obediente. Volte aqui apenas quando precisar.</color>",
  str_n29_detective_point_desc_1 = "Gentil Senhorita Babá.\nSuas mãos são tão finas e tão ásperas, assim como as mãos da mamãe.\nDe todos os adultos, ela é a única Hati confia mais.\nSempre que há <color=#902121>algo que ela não ousaria perguntar a mais ninguém, ela sempre pode perguntar a ela.</color>",
  str_n29_detective_point_desc_2 = "Um zelador que adora vadiar.\nEla não gosta de crianças e sempre zomba de Hati. Ela é vil!\nNo entanto, ela é a única que se atreve a contar Hati <color=#902121>segredos que os outros adultos não contariam.</color>",
  str_n29_detective_point_desc_3 = "Uma menina que fala muito baixinho e adora rir.\nHati sentiu que talvez ela pudesse <color=#902121>faça amizade com ela...</color>\nSempre parece haver algo ameaçador escondido em seu sorriso, mas <color=#902121>o que pode ser feito para ajudá-la?</color>",
  str_n29_detective_point_desc_4 = "O lacaio bajulador do Rei Malvado.\nNo entanto, <color=#902121>O Rei Malvado não gosta dele...</color>\n<color=#902121>Por que ele parece satisfeito seguindo o Rei Malvado por aí?</color>",
  str_n29_detective_point_desc_5 = "Todo mundo odeia o Rei Malvado.\nEle sempre <color=#902121>gosta de intimidar as pessoas</color>, então por que alguém iria gostar dele?\n<color=#902121>Sem amigos, é impossível abrir o coração para qualquer pessoa.</color>\nTalvez se você fosse <color=#902121>chame-o, ele falaria com você.</color>",
  str_n29_detective_point_desc_6 = "A velha diretora do orfanato sempre parece estar <color=#902121>ressente absolutamente tudo.</color>\nHati não gosta quando ela olha para ela. <color=#902121>Se ao menos ela não estivesse aqui.</color>",
  str_n29_detective_point_desc_7 = "O entregador do orfanato gosta de rir alto.\nele parece <color=#902121>gosta de estar perto de crianças</color> e conversa com Hati sobre várias coisas.\nDele <color=#902121>transporte</color> é realmente muito curioso. O que poderia estar dentro?",
  str_n29_detective_point_desc_8 = "Um investidor no orfanato que está <color=#902121>sempre olhando para Hati.</color>\nHati não gosta dele.",
  str_n29_detective_point_desc_9 = "é aqui Hati e as outras crianças dormem e brincam.\n<color=#902121>Seus segredos</color> geralmente se escondem com eles debaixo das cobertas.\n<color=#902121>Senhorita Babá</color> também gosta de ficar aqui. Às vezes, ela senta aqui, suspirando.",
  str_n29_detective_point_desc_10 = "Os adultos dizem que o tempo lá fora está ruim, então não podemos sair para brincar. Mas sempre há crianças desobedientes que <color=#902121>escapam.</color> <color=#902121>Sr. O investidor</color> também está aqui... Hati não gosta dele.",
  str_n29_detective_point_desc_11 = "Tosse, tosse... Tem tanta poeira aqui.\nA área dos bastidores está repleta de adereços de performance feitos pelas crianças. Poderia haver algum <color=#902121>tesouros</color> escondido aqui?",
  str_n29_detective_point_desc_12 = "Hati nunca viu um quarto tão bonito. Mas não há janelas, como na casa de Hati!\nNinguém está aqui agora, então se você der uma olhada no <color=#902121>os segredos do antigo diretor</color>, alguém vai descobrir?",
  str_n29_detective_character_random_1 = "Qual é o problema? Está com fome?",
  str_n29_detective_character_random_2 = "Se houver alguma coisa que importe, certifique-se de me dizer.",
  str_n29_detective_character_random_3 = "Tosse, tosse... Está tudo bem, não se preocupe comigo.",
  str_n29_detective_character_random_4 = "Pare de me incomodar.",
  str_n29_detective_character_random_5 = "O que você está procurando por mim, cão vadio?",
  str_n29_detective_character_random_6 = "Se você não tem dinheiro para mim, vá embora.",
  str_n29_detective_character_random_7 = "Você aí!",
  str_n29_detective_character_random_8 = "Heehee, você está aqui para conversar comigo de novo, certo?",
  str_n29_detective_character_random_9 = "Quer brincar comigo?",
  str_n29_detective_character_random_10 = "Eu não disse nada de ruim sobre ninguém!",
  str_n29_detective_character_random_11 = "A grande e misericordiosa Senhora Diretora, todos a amam!",
  str_n29_detective_character_random_12 = "O orfanato é o melhor lugar do mundo.",
